require_once __DIR__.'/../../includes/cors.php';require_once __DIR__.'/../../includes/response.php';require_once __DIR__.'/../../includes/helpers.php';require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/admin-audit.php';
if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['success'=>false,'message'=>'Method not allowed'],405);$user=require_auth($pdo);require_role($user,['super_admin']);$in=get_json_input();$sid=(int)($in['subscription_id']??0);$amount=(float)($in['amount']??-1);$status=(string)($in['status']??'paid');$currency=strtoupper(trim((string)($in['currency']??'IRR')));if(!$sid||$amount<0||!in_array($status,['pending','paid','failed','refunded','cancelled'],true)||!preg_match('/^[A-Z]{3}$/',$currency))json_response(['success'=>false,'message'=>'Invalid payment data'],422);
try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT tenant_id,plan_id FROM tenant_subscriptions WHERE id=:id');$q->execute([':id'=>$sid]);$s=$q->fetch();if(!$s)throw new ApiPublicException('Subscription not found');$q=$pdo->prepare("INSERT INTO subscription_payments(tenant_id,subscription_id,amount,currency,payment_method,reference_number,status,paid_at,description,created_by) VALUES(:t,:s,:a,:c,:m,:r,:st,:paid,:d,:by)");$q->execute([':t'=>$s['tenant_id'],':s'=>$sid,':a'=>$amount,':c'=>$currency,':m'=>trim((string)($in['payment_method']??'manual')),':r'=>($r=trim((string)($in['reference_number']??'')))!==''?$r:null,':st'=>$status,':paid'=>$status==='paid'?(!empty($in['paid_at'])?(new DateTimeImmutable($in['paid_at']))->format('Y-m-d H:i:s'):date('Y-m-d H:i:s')):null,':d'=>($d=trim((string)($in['description']??'')))!==''?$d:null,':by'=>$user['id']]);$id=(int)$pdo->lastInsertId();admin_audit_log($pdo,$user,'subscription.payment_created','payment',$id,'Manual subscription payment recorded',null,['amount'=>$amount,'status'=>$status],['tenant_id'=>$s['tenant_id'],'plan_id'=>$s['plan_id']]);$pdo->commit();json_response(['success'=>true,'message'=>'Payment recorded','payment_id'=>$id],201);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'message'=>safe_api_exception_message($e,'Payment could not be recorded.')],422);}
